INSERT INTO `chat_messages` (`id`, `chatSessionId`, `user_id`, `role`, `message`, `channel`, `metadata`, `createdAt`, `updatedAt`, `customer_phone`, `ai_responder`) VALUES
(141, 1, 'LFGKT49002', 'ai', 'Baik, Kak, saya catat. Untuk target waktu belinya, nanti Bapak infokan lagi ya, tidak masalah 😊\n\nKalau begitu, sekarang — untuk proses pengambilan keputusannya, kalau nanti ada rumah yang cocok, apakah langsung bisa Bapak putuskan sendiri atau perlu diskusi dulu sama istri? 📅', 'whatsapp', '{\"aiProvider\":\"deepseek\",\"contextSource\":\"db_catalog\"}', '2026-07-27 06:51:02', '2026-07-27 06:51:02', NULL, NULL),
(142, 1, 'LFGKT49002', 'customer', 'saya akan diskusi dengan istri untuk deal pembeliannya', 'whatsapp', '{\"agentName\":\"LEO FELIX\",\"messageId\":\"kirimi_1785135102870\",\"platform\":\"kirimi\"}', '2026-07-27 06:51:54', '2026-07-27 06:51:54', NULL, NULL),
(143, 1, 'LFGKT49002', 'ai', 'Baik, Kak! Saya catat, kalau ada rumah yang cocok nanti akan didiskusikan dulu dengan istri ya 😊\n\nNah, sekarang — ada target kapan proses belinya selesai? 📅', 'whatsapp', '{\"aiProvider\":\"deepseek\",\"contextSource\":\"db_catalog\"}', '2026-07-27 06:51:58', '2026-07-27 06:51:58', NULL, NULL),
(144, 1, 'LFGKT49002', 'customer', 'Hi... Mau booking villa di Surabaya', 'whatsapp', '{\"agentName\":\"LEO FELIX\",\"messageId\":\"kirimi_1785478072754\",\"platform\":\"kirimi\"}', '2026-07-31 06:08:04', '2026-07-31 06:08:04', NULL, NULL),
(145, 1, 'LFGKT49002', 'ai', 'Hampir lengkap! Untuk *sewa Villa di Surabaya* — 💰\n\nKisaran harga yang Anda inginkan berapa?\n_(Contoh: 3-7 juta/bulan, di bawah 500 juta, atau 1-2 miliar)_\n\nJika belum ada angka pasti, cukup ceritakan apakah lebih prefer yang *terjangkau* atau *menengah ke atas* — saya tetap bisa carikan yang sesuai 😊\n\nSalam hangat,\n*LEO FELIX*\n*Elevan Property*', 'whatsapp', '{\"aiProvider\":\"qualification\",\"contextSource\":\"db_catalog\"}', '2026-07-31 06:08:09', '2026-07-31 06:08:09', NULL, NULL),
(146, 1, 'LFGKT49002', 'customer', 'Saya mau sewa villa dgn badget 2-2.6 juta/minggu. Karena saya mau liburan selama 1 minggu di Surabaya', 'whatsapp', '{\"agentName\":\"LEO FELIX\",\"messageId\":\"kirimi_1785478144065\",\"platform\":\"kirimi\"}', '2026-07-31 06:09:16', '2026-07-31 06:09:16', NULL, NULL),
(147, 1, 'LFGKT49002', 'ai', 'Baik, Kak! Saya catat untuk sewa *Villa* di *Surabaya* dengan budget **Rp 2.000.000 - Rp 2.600.000/minggu** untuk liburan 1 minggu 😊\n\nDi area atau kawasan mana di *Surabaya* yang Anda pertimbangkan? 📍 Misalnya Pakuwon, Darmo, Rungkut, Gubeng, Kenjeran, atau area lainnya?', 'whatsapp', '{\"aiProvider\":\"deepseek\",\"contextSource\":\"db_catalog\"}', '2026-07-31 06:09:23', '2026-07-31 06:09:23', NULL, NULL),
